import fs from 'node:fs';import {createHash} from 'node:crypto';
const files=['execution/production-activation.mjs','execution/controller.mjs','execution/settlement-controller.mjs','execution/settlement-controller.test.mjs','execution/transport.mjs','execution/production-launch.md','execution/README.md','live-paper/transport-network-budget.mjs','live-paper/market-sweep.mjs','live-paper/runner.mjs','live-paper/runner-lifecycle.test.mjs','live-paper/production-network-budget.test.mjs','live-paper/production-metadata.mjs','live-paper/production-metadata.test.mjs','data/deploy-production-collector-20261004.mjs','data/production-collector-deployment-20261004.json','data/prepare-production-bank-20261004.mjs','data/production-bank-stage-20261004.json','data/kansas-current-contract-20261004.json','data/prepare-production-publication-20261004.mjs'];
const pack='data/production-integration-publication-pack-20261004.json',arg=process.argv.indexOf('--chunk');
if(arg!==-1){const text=fs.readFileSync(pack,'utf8'),n=Number(process.argv[arg+1]);if(!Number.isSafeInteger(n)||n<0)throw Error('CHUNK');console.log(JSON.stringify(text.slice(n*12000,(n+1)*12000)));}
else{const elements=files.map(path=>{const content=fs.readFileSync(path,'utf8');if(/ace_[a-f0-9]{30,}|sk-[a-zA-Z0-9_-]{20,}|-----BEGIN [A-Z ]*PRIVATE KEY-----|https:\/\/[^\s\"\']+token=[A-Za-z0-9%]+/i.test(content))throw Error('SECRET_CHECK '+path);return{path,mode:'100644',type:'blob',content};}),bytes=JSON.stringify(elements);fs.writeFileSync(pack,bytes);console.log(JSON.stringify({files:files.length,characters:bytes.length,chunks:Math.ceil(bytes.length/12000),sha256:createHash('sha256').update(bytes).digest('hex')}));}
